2	import assert from 'node:assert/strict';
3	import { readFileSync } from 'node:fs';
4	import { join, dirname } from 'node:path';
5	import { fileURLToPath } from 'node:url';
6	import { makeRepo, cleanup } from '../../engine-tests/helpers.mjs';
7	import { buildContext } from '../../engine/checks/helpers/repo-context.mjs';
8	import { runRule } from '../../engine/checks/helpers/work.mjs';
9	import { discoverPacks, resolveDeclaredPacks, packEntryId } from '../../engine/pack_loader/pack-registry.mjs';
10	import basicsPack from '../../packs/basics/pack.mjs';
11	import corePack from '../../packs/core/pack.mjs';
12	import coreDeclared from '../../packs/core/core-declared.mjs';
13	
14	// `core` is mandatory in every Claudinite member. Nothing in a single module can
15	// assert that on its own — it is three facts in three places, and this file holds
16	// all three together so none of them can move without the others:
17	//
18	//   1. the requires EDGE that makes core reach every member (basics -> core),
19	//   2. the CLOSURE actually materializing the declaration from that edge, and
20	//   3. the CHECK that reports a member whose declaration lacks it.
21	//
22	// The check itself spells `core` as a literal, because a rule's `run` is
23	// synchronous and reading a manifest is a dynamic import. Case 1 is the drift
24	// guard for that literal.
25	const REPO = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
26	
27	test('basics requires core — the edge that makes it mandatory', () => {
28	  assert.ok(
29	    basicsPack.requires?.includes('core'),
30	    'basics must require core: it is the pack seeded everywhere, so its requires closure is what carries core into every member. Without this edge nothing declares core and packs/core/core-declared.mjs guards a literal that means nothing.',
31	  );
32	});
33	
34	test('the requires closure materializes core into a declaration that names only basics', async () => {
35	  const { packs } = await discoverPacks({ localRoot: REPO });
36	  const resolved = resolveDeclaredPacks(['basics'], packs).map(packEntryId);
37	  assert.ok(resolved.includes('core'), `resolving ["basics"] gave ${JSON.stringify(resolved)} — core must be in the closure`);
38	});
39	
40	test('core-declared: silent on a member that declares core, fires on one that does not', () => {
41	  const withCore = makeRepo({ changed: { '.claudinite-checks.json': JSON.stringify({ packs: ['core', 'basics'] }) } });
42	  const without = makeRepo({ changed: { '.claudinite-checks.json': JSON.stringify({ packs: ['basics'] }) } });
43	  try {
44	    assert.equal(runRule(coreDeclared, buildContext({ root: withCore, mode: 'all' })).length, 0);
45	    const findings = runRule(coreDeclared, buildContext({ root: without, mode: 'all' }));
46	    assert.equal(findings.length, 1, JSON.stringify(findings, null, 2));
47	    assert.equal(findings[0].file, '.claudinite-checks.json');
48	    assert.match(findings[0].what, /core/);
49	  } finally { cleanup(withCore); cleanup(without); }
50	});
51	
52	test('core-declared: an entry-object declaration counts, and a non-member is inert', () => {
53	  const objectEntry = makeRepo({ changed: { '.claudinite-checks.json': JSON.stringify({ packs: [{ id: 'core', via: ['basics'] }] }) } });
54	  const notAMember = makeRepo({ changed: { 'README.md': '# hi\n' } });
55	  try {
56	    assert.equal(runRule(coreDeclared, buildContext({ root: objectEntry, mode: 'all' })).length, 0);
57	    assert.equal(runRule(coreDeclared, buildContext({ root: notAMember, mode: 'all' })).length, 0);
58	  } finally { cleanup(objectEntry); cleanup(notAMember); }
59	});
60	
61	test('the canon home declares core itself — baselining never reaches it', () => {
62	  // The nightly backfill that seeds a pack across the fleet is gated `!isHome`, so
63	  // this repo's own declaration is the one nothing delivers to. If it drifts, every
64	  // core rule stops running in the repo that authors them.
65	  const config = JSON.parse(readFileSync(join(REPO, '.claudinite-checks.json'), 'utf8'));
66	  assert.ok(config.packs.map(packEntryId).includes('core'), 'the canon home must declare core in its own .claudinite-checks.json');
67	});
68	
69	test('the core-seed record declares exactly the pack this manifest ships', async () => {
70	  const { default: record } = await import('../../packs/core/migrations/2026-08-14-core-seed/migration.mjs');
71	  assert.deepEqual(record.declarePacks.map((p) => p.id), [corePack.id]);
72	  assert.ok(record.version <= corePack.version, `the record declares version ${record.version}; the pack ships ${corePack.version} — a record above its pack's version re-applies every cycle forever`);
73	});

