import sys, json, urllib.request

def probe(full):
    url = f"https://raw.githubusercontent.com/{full}/HEAD/.claudinite-checks.json"
    try:
        with urllib.request.urlopen(url, timeout=30) as r:
            cfg = json.load(r)
    except Exception as e:
        return (full, "NO-DECLARATION", str(e)[:40], "", "", "")
    ids = []
    for e in cfg.get("packs", []):
        i = e if isinstance(e, str) else (e or {}).get("id")
        if i:
            ids.append(i.split("/")[-1])
    st = cfg.get("claudinite") or {}
    ref = (st.get("ref") or "-")[:7]
    upd = (st.get("updated") or "-")[:10]
    corev = (st.get("packVersions") or {}).get("core", "-")
    return (full, "core" if "core" in ids else "MISSING", ref,
            str(st.get("engineVersion", "-")), str(corev), upd)

rows = [probe(a) for a in sys.argv[1:]]
w = [max(len(str(r[i])) for r in rows) for i in range(6)]
hdr = ("repo", "core?", "ref", "eng", "corev", "updated")
w = [max(w[i], len(hdr[i])) for i in range(6)]
print("  ".join(h.ljust(w[i]) for i, h in enumerate(hdr)))
for r in rows:
    print("  ".join(str(c).ljust(w[i]) for i, c in enumerate(r)))
EOF
python3 readback.py missingbulb/Sheepdog missingbulb/Claudinite

